def iterate_until_stable(modifier, spec, max_steps=1000):
    current = spec
    levels = [current.level]
    for i in range(1, max_steps + 1):
        next_spec = modifier.modify(current)
        levels.append(next_spec.level)
        if next_spec.level == current.level:
            return next_spec, i, levels
        current = next_spec
    return current, max_steps, levels

def check_diagonal_barrier(family, diag_level, test_points):
    target_pred = family[diag_level].pred
    diagonal_values = {x: not target_pred(x) for x in test_points}
    matches = []
    for i, spec in enumerate(family):
        if spec.level == diag_level:
            match = all(spec.pred(x) == diagonal_values[x] for x in test_points)
            if match:
                matches.append(i)
    return {'blocked': len(matches) == 0, 'matches': matches}

algorithms.pseudocode:
Build tower of n levels:
  for level = 0 to n-1:
    T[level].provable ← basic_sentences ∪ {Con(T[j]) : j < level}
    T[level] does NOT prove Con(T[level])

algorithms.code:
def build_demo_tower(n_levels):
    theories = []
    for level in range(n_levels):
        provable_set = set()
        provable_set.add(f'0 = 0 at level {level}')
        for j in range(level):
            provable_set.add(f'Con(T_{j})')
        theories.append(LevelTheory(level=level, sentences=list(provable_set),
                                     provable=lambda s, ps=provable_set: s in ps,
                                     con_statement=f'T_{level}'))
    return ConsistencyTower(theories=theories)
